/**
 * PerformanceOptimizer - 性能优化模块
 * 懒加载 + 虚拟列表 + 智能缓存
 */
import { toolRegistry } from './registry.js';

// 缓存配置
const CACHE_CONFIG = {
  maxSize: 50 * 1024 * 1024, // 50MB
  ttl: 5 * 60 * 1000, // 5分钟
  checkInterval: 30000 // 30秒检查一次
};

// 存储键
const CACHE_KEY = 'ai-creator-perf-cache';
const USAGE_STATS_KEY = 'ai-creator-usage-stats';

// 内存缓存
const memoryCache = new Map();
let cacheSize = 0;

// 初始化
export function initPerformanceOptimizer() {
  // 启动缓存清理定时器
  setInterval(cleanExpiredCache, CACHE_CONFIG.checkInterval);
  
  // 恢复持久化缓存
  restoreCacheFromStorage();
  
  console.log('[PerfOptimizer] Initialized');
}

// ============ 缓存系统 ============

/**
 * 设置缓存
 */
export function setCache(key, value, ttl = CACHE_CONFIG.ttl) {
  const entry = {
    value,
    timestamp: Date.now(),
    ttl,
    size: estimateSize(value)
  };
  
  memoryCache.set(key, entry);
  cacheSize += entry.size;
  
  // 检查缓存大小
  if (cacheSize > CACHE_CONFIG.maxSize) {
    evictOldestEntries();
  }
  
  // 持久化
  persistCacheToStorage();
}

/**
 * 获取缓存
 */
export function getCache(key) {
  const entry = memoryCache.get(key);
  
  if (!entry) return null;
  
  // 检查过期
  if (Date.now() - entry.timestamp > entry.ttl) {
    memoryCache.delete(key);
    cacheSize -= entry.size;
    persistCacheToStorage();
    return null;
  }
  
  return entry.value;
}

/**
 * 删除缓存
 */
export function deleteCache(key) {
  const entry = memoryCache.get(key);
  if (entry) {
    cacheSize -= entry.size;
    memoryCache.delete(key);
    persistCacheToStorage();
  }
}

/**
 * 清除所有缓存
 */
export function clearCache() {
  memoryCache.clear();
  cacheSize = 0;
  persistCacheToStorage();
}

/**
 * 获取缓存统计
 */
export function getCacheStats() {
  return {
    entries: memoryCache.size,
    size: cacheSize,
    maxSize: CACHE_CONFIG.maxSize,
    usagePercent: ((cacheSize / CACHE_CONFIG.maxSize) * 100).toFixed(1)
  };
}

// 清理过期条目
function cleanExpiredCache() {
  const now = Date.now();
  let cleaned = 0;
  let cleanedSize = 0;
  
  for (const [key, entry] of memoryCache.entries()) {
    if (now - entry.timestamp > entry.ttl) {
      cleanedSize += entry.size;
      memoryCache.delete(key);
      cleaned++;
    }
  }
  
  cacheSize -= cleanedSize;
  
  if (cleaned > 0) {
    persistCacheToStorage();
    console.log(`[PerfOptimizer] Cleaned ${cleaned} expired entries, ${cleanedSize} bytes`);
  }
}

// 驱逐最旧条目
function evictOldestEntries() {
  const entries = Array.from(memoryCache.entries())
    .sort((a, b) => a[1].timestamp - b[1].timestamp);
  
  let targetSize = CACHE_CONFIG.maxSize * 0.7; // 清理到70%
  
  while (cacheSize > targetSize && entries.length > 0) {
    const [key, entry] = entries.shift();
    cacheSize -= entry.size;
    memoryCache.delete(key);
  }
}

// 估算大小
function estimateSize(value) {
  try {
    return new Blob([JSON.stringify(value)]).size;
  } catch {
    return 1024; // 默认1KB
  }
}

// 持久化到localStorage
function persistCacheToStorage() {
  try {
    const data = {};
    for (const [key, entry] of memoryCache.entries()) {
      // 只持久化非过期项
      if (Date.now() - entry.timestamp <= entry.ttl) {
        data[key] = entry;
      }
    }
    
    const json = JSON.stringify(data);
    if (json.length < 5 * 1024 * 1024) { // 不超过5MB
      localStorage.setItem(CACHE_KEY, json);
    }
  } catch (e) {
    // localStorage 满了，清理后重试
    clearCache();
    try {
      localStorage.setItem(CACHE_KEY, '{}');
    } catch {
      // ignore
    }
  }
}

// 从localStorage恢复
function restoreCacheFromStorage() {
  try {
    const json = localStorage.getItem(CACHE_KEY);
    if (!json) return;
    
    const data = JSON.parse(json);
    let restored = 0;
    
    for (const [key, entry] of Object.entries(data)) {
      // 检查是否过期
      if (Date.now() - entry.timestamp <= entry.ttl) {
        memoryCache.set(key, entry);
        cacheSize += entry.size;
        restored++;
      }
    }
    
    if (restored > 0) {
      console.log(`[PerfOptimizer] Restored ${restored} cache entries`);
    }
  } catch {
    localStorage.removeItem(CACHE_KEY);
  }
}

// ============ 使用统计 ============

/**
 * 记录工具使用
 */
export function recordToolUsage(toolId) {
  const stats = getUsageStats();
  
  if (!stats[toolId]) {
    stats[toolId] = { count: 0, lastUsed: null };
  }
  
  stats[toolId].count++;
  stats[toolId].lastUsed = Date.now();
  
  saveUsageStats(stats);
}

/**
 * 获取使用统计
 */
export function getUsageStats() {
  try {
    return JSON.parse(localStorage.getItem(USAGE_STATS_KEY) || '{}');
  } catch {
    return {};
  }
}

/**
 * 获取热门工具
 */
export function getHotTools(limit = 10) {
  const stats = getUsageStats();
  
  return Object.entries(stats)
    .map(([toolId, data]) => ({ toolId, ...data }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/**
 * 获取最近使用
 */
export function getRecentTools(limit = 10) {
  const stats = getUsageStats();
  
  return Object.entries(stats)
    .filter(([_, data]) => data.lastUsed)
    .map(([toolId, data]) => ({ toolId, ...data }))
    .sort((a, b) => (b.lastUsed || 0) - (a.lastUsed || 0))
    .slice(0, limit);
}

function saveUsageStats(stats) {
  try {
    // 只保留前100个工具
    const entries = Object.entries(stats)
      .sort((a, b) => (b[1].lastUsed || 0) - (a[1].lastUsed || 0))
      .slice(0, 100);
    
    const trimmed = Object.fromEntries(entries);
    localStorage.setItem(USAGE_STATS_KEY, JSON.stringify(trimmed));
  } catch {
    // ignore
  }
}

// ============ 虚拟列表 ============

/**
 * 创建虚拟列表
 */
export function createVirtualList(container, options = {}) {
  const {
    itemHeight = 60,
    overscan = 3,
    renderItem = () => ''
  } = options;
  
  let scrollTop = 0;
  let containerHeight = 0;
  let items = [];
  
  const el = document.createElement('div');
  el.className = 'virtual-list';
  el.style.cssText = 'overflow-y: auto; position: relative;';
  
  const content = document.createElement('div');
  content.className = 'virtual-list-content';
  el.appendChild(content);
  
  const spacer = document.createElement('div');
  spacer.className = 'virtual-list-spacer';
  content.appendChild(spacer);
  
  const visibleContainer = document.createElement('div');
  visibleContainer.className = 'virtual-list-visible';
  content.appendChild(visibleContainer);
  
  function update() {
    const rect = el.getBoundingClientRect();
    containerHeight = rect.height;
    
    const startIndex = Math.max(0, Math.floor(scrollTop / itemHeight) - overscan);
    const endIndex = Math.min(
      items.length - 1,
      Math.ceil((scrollTop + containerHeight) / itemHeight) + overscan
    );
    
    const totalHeight = items.length * itemHeight;
    spacer.style.height = totalHeight + 'px';
    spacer.style.paddingTop = (startIndex * itemHeight) + 'px';
    
    visibleContainer.innerHTML = '';
    
    for (let i = startIndex; i <= endIndex; i++) {
      const itemEl = document.createElement('div');
      itemEl.className = 'virtual-list-item';
      itemEl.style.height = itemHeight + 'px';
      itemEl.style.position = 'absolute';
      itemEl.style.top = (i * itemHeight) + 'px';
      itemEl.style.left = '0';
      itemEl.style.right = '0';
      itemEl.innerHTML = renderItem(items[i], i);
      visibleContainer.appendChild(itemEl);
    }
  }
  
  el.addEventListener('scroll', () => {
    scrollTop = el.scrollTop;
    update();
  });
  
  function setItems(newItems) {
    items = newItems || [];
    update();
  }
  
  function scrollToIndex(index) {
    el.scrollTop = index * itemHeight;
    update();
  }
  
  // 暴露方法
  el.setItems = setItems;
  el.scrollToIndex = scrollToIndex;
  el.update = update;
  
  // 初始更新
  requestAnimationFrame(update);
  
  return el;
}

// ============ 图片懒加载 ============

const lazyImageObserver = new IntersectionObserver((entries) => {
  for (const entry of entries) {
    if (entry.isIntersecting) {
      const img = entry.target;
      const src = img.dataset.src;
      
      if (src) {
        img.src = src;
        img.removeAttribute('data-src');
        img.classList.remove('lazy-loading');
        lazyImageObserver.unobserve(img);
      }
    }
  }
}, {
  rootMargin: '100px 0px',
  threshold: 0.01
});

/**
 * 观察懒加载图片
 */
export function observeLazyImages(root = document) {
  const images = root.querySelectorAll('img[data-src]');
  for (const img of images) {
    img.classList.add('lazy-loading');
    lazyImageObserver.observe(img);
  }
}

/**
 * 取消观察
 */
export function unobserveLazyImages(root = document) {
  const images = root.querySelectorAll('img[data-src]');
  for (const img of images) {
    lazyImageObserver.unobserve(img);
  }
}

// ============ 预加载 ============

/**
 * 预加载图片
 */
export function preloadImage(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = url;
  });
}

/**
 * 批量预加载图片
 */
export function preloadImages(urls, onProgress) {
  let loaded = 0;
  const total = urls.length;
  
  return Promise.all(urls.map(url => 
    preloadImage(url)
      .then(() => {
        loaded++;
        onProgress?.(loaded / total);
      })
      .catch(() => {
        loaded++;
        onProgress?.(loaded / total);
      })
  ));
}

// ============ 防抖/节流 ============

/**
 * 防抖
 */
export function debounce(fn, delay) {
  let timer = null;
  return function(...args) {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      fn.apply(this, args);
    }, delay);
  };
}

/**
 * 节流
 */
export function throttle(fn, limit) {
  let inThrottle = false;
  return function(...args) {
    if (!inThrottle) {
      fn.apply(this, args);
      inThrottle = true;
      setTimeout(() => inThrottle = false, limit);
    }
  };
}

// ============ 性能监控 ============

const perfMarks = new Map();

/**
 * 记录性能标记
 */
export function mark(label) {
  perfMarks.set(label, Date.now());
}

/**
 * 测量性能
 */
export function measure(label, startMark) {
  const start = perfMarks.get(startMark) || Date.now();
  const end = Date.now();
  const duration = end - start;
  
  console.log(`[Perf] ${label}: ${duration}ms`);
  return duration;
}

/**
 * 获取内存使用
 */
export function getMemoryUsage() {
  if (performance.memory) {
    return {
      usedJSHeapSize: performance.memory.usedJSHeapSize,
      totalJSHeapSize: performance.memory.totalJSHeapSize,
      jsHeapSizeLimit: performance.memory.jsHeapSizeLimit
    };
  }
  return null;
}

export default {
  initPerformanceOptimizer,
  setCache,
  getCache,
  deleteCache,
  clearCache,
  getCacheStats,
  recordToolUsage,
  getUsageStats,
  getHotTools,
  getRecentTools,
  createVirtualList,
  observeLazyImages,
  unobserveLazyImages,
  preloadImage,
  preloadImages,
  debounce,
  throttle,
  mark,
  measure,
  getMemoryUsage
};